import json,re
records=[json.loads(l) for l in p.read_text().splitlines()]
acts=[]
for rec in records:
    msg=rec.get('message',{})
    if msg.get('role')=='assistant':
        for part in msg.get('content',[]):
            if part.get('type')=='text' and part.get('text','').startswith('{"action"'):
                try:
                    obj=json.loads(part['text'])
                    if obj.get('action')=='submit': acts.append(obj['grid'])
                except Exception as e: pass
print(len(acts),[(len(g), sorted(set(map(len,g)))) for g in acts])
